import{modal}from './ui.js';
import{actionIcon,actionLabel}from './action-icons.js';
export const SALAH_TV_URL='https://skodytunez-maker.github.io/salah/';
export function tvEntryMarkup(){return '<button type="button" class="list-button" data-tv-app><span class="menu-item-label">'+actionIcon('tv')+'На телевизор</span><small>Приложение и звук</small></button>';}
export function showTvOutput({requestAudio,doc=document,nav=navigator}={}){
 const instructions={apple:['Подключите телефон и телевизор с AirPlay к одной сети Wi-Fi.','Откройте Пункт управления на iPhone или iPad и выберите «Повтор экрана».','Выберите телевизор, затем вернитесь в SALAH. Если телевизор покажет код, введите его на телефоне.'],android:['Подключите телефон и телевизор к одной сети Wi-Fi.','Для телевизора с Google Cast откройте Google Home, выберите устройство и нажмите «Транслировать экран». Названия пунктов могут отличаться.','На Samsung и других телефонах также может быть доступен «Smart View» или «Трансляция» в панели быстрых настроек. Выберите телевизор и вернитесь в SALAH.'],computer:['Откройте SALAH в Chrome на компьютере и подключите его к той же сети Wi-Fi, что и телевизор с Google Cast.','В меню Chrome выберите «Транслировать, сохранить, поделиться», затем «Трансляция».','Выберите телевизор и передачу вкладки SALAH.']};
 const initial=/iPhone|iPad|iPod/i.test(nav?.userAgent||'')?'apple':/Android/i.test(nav?.userAgent||'')?'android':'computer';
 modal('<div class="modal-heading"><h2>'+actionIcon('tv')+' На телевизор</h2><button type="button" class="text-button" data-close>Закрыть</button></div><section class="tv-output"><h3>Приложение целиком</h3><p>Покажите экран телефона вместе с Кораном, обоями и всеми разделами SALAH.</p><div class="tv-output-tabs" role="group" aria-label="Ваше устройство">'+[['apple','iPhone / iPad'],['android','Android'],['computer','Компьютер']].map(([id,label])=>'<button type="button" data-tv-platform="'+id+'" aria-pressed="false">'+label+'</button>').join('')+'</div><ol data-tv-instructions></ol><p class="muted">Повтор экрана включается в системе телефона. Если телевизор не поддерживает нужный способ, используйте его браузер или совместимое устройство подключения.</p><h3>Только звук</h3><p>Для уже запущенного чтения выберите телевизор или колонку в системном списке устройств.</p><button type="button" class="button secondary" data-tv-audio '+(requestAudio?'':'disabled')+'>'+actionLabel('tv','Выбрать устройство')+'</button><p data-tv-status role="status" class="muted"></p><details class="tv-browser-option"><summary>Открыть SALAH в браузере телевизора</summary><p>Если у телевизора есть браузер, откройте в нём эту ссылку:</p><input class="tv-public-url" readonly aria-label="Ссылка SALAH для телевизора" value="'+SALAH_TV_URL+'"></details></section>');
 const root=doc.getElementById('modal-content'),dialog=doc.getElementById('modal');
 const choose=platform=>{if(!Object.hasOwn(instructions,platform))return;root.querySelector('[data-tv-instructions]').innerHTML=instructions[platform].map(text=>'<li>'+text+'</li>').join('');for(const b of root.querySelectorAll('[data-tv-platform]'))b.setAttribute('aria-pressed',String(b.dataset.tvPlatform===platform));};
 for(const b of root.querySelectorAll('[data-tv-platform]'))b.onclick=()=>choose(b.dataset.tvPlatform);choose(initial);
 const button=root.querySelector('[data-tv-audio]'),status=root.querySelector('[data-tv-status]');let pending=false;
 button.onclick=()=>{if(!requestAudio||pending)return;pending=true;button.disabled=true;status.textContent='';let task;try{task=requestAudio();}catch{task=Promise.resolve({status:'unavailable'});}
 Promise.resolve(task).then(result=>{if(!dialog.open||!status.isConnected)return;status.textContent={picker:'Выберите устройство в системном окне.',connected:'Устройство для звука подключено.',cancelled:'',denied:'Передача не разрешена. Можно использовать системный повтор экрана.',unavailable:'Прямая передача звука здесь недоступна. Используйте повтор экрана по инструкции выше.','no-media':'Сначала запустите чтение Корана или рукъи.'}[result?.status]||'Используйте повтор экрана по инструкции выше.';}).catch(()=>{if(dialog.open&&status.isConnected)status.textContent='Используйте повтор экрана по инструкции выше.';}).finally(()=>{pending=false;if(button.isConnected)button.disabled=false;});
 };
}
